workspace "Parcel Tracker" "A parcel delivery tracking platform, owned and operated by our company." {

    model {
        customer = person "Customer" "A customer who uses the platform to look up the status of their parcels."

        parcelTracker = softwareSystem "Parcel Tracker" "A parcel delivery tracking platform, owned and operated by our company." {
            webPortal = container "Web Portal" "A web portal where customers look up shipments. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Web application"
            dispatchService = container "Dispatch Service" "A service that assigns parcels to couriers. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Service"
            database = container "Database" "Stores shipments and dispatch records." "SQL database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "An email delivery provider operated by a different organization." tags: "External"

        customer -> webPortal "Looks up the status of their parcels" "HTTPS/JSON"
        webPortal -> database "Reads shipment and dispatch records" "SQL"
        dispatchService -> database "Writes dispatch records" "SQL"
        dispatchService -> emailProvider "Sends customer notification emails" "SMTP"
    }

    views {
        systemContext parcelTracker "SystemContext" "System context diagram of the Parcel Tracker system." {
            include *
            autoLayout
        }

        container parcelTracker "Containers" "Container diagram of the Parcel Tracker system." {
            include *
            autoLayout
        }
    }
}

